-- Aparência própria de cada link nomeado: tabela nova, sem tocar nas
-- existentes. Links atuais seguem mostrando a aparência do board até a
-- primeira alteração feita por quem entra por eles.
CREATE TABLE `aparencias_link` (
	`link_id` integer PRIMARY KEY NOT NULL,
	`tipo` text DEFAULT 'predefinido' NOT NULL,
	`chave_predefinida` text DEFAULT 'padrao' NOT NULL,
	`gradiente_formato` text DEFAULT 'linear' NOT NULL,
	`gradiente_angulo` integer DEFAULT 135 NOT NULL,
	`gradiente_cor_inicial` text DEFAULT '#dbeafe' NOT NULL,
	`gradiente_cor_intermediaria` text,
	`gradiente_cor_final` text DEFAULT '#ede9fe' NOT NULL,
	`imagem_identificador` text,
	`imagem_formato` text,
	`imagem_hash` text,
	`imagem_cor_media` text,
	`cor_titulos` text DEFAULT '#ffffff' NOT NULL,
	`cor_colunas` text DEFAULT '#f4f6f3' NOT NULL,
	`opacidade_titulos` integer DEFAULT 90 NOT NULL,
	`opacidade_colunas` integer DEFAULT 90 NOT NULL,
	`tom_texto` text DEFAULT 'automatico' NOT NULL,
	`cor_prioridade_critica` text,
	`cor_prioridade_alta` text,
	`cor_prioridade_media` text,
	`cor_prioridade_baixa` text,
	`atualizado_em` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) NOT NULL,
	FOREIGN KEY (`link_id`) REFERENCES `links_compartilhamento`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "aparencias_link_tipo_valido" CHECK("aparencias_link"."tipo" IN ('predefinido', 'gradiente', 'imagem')),
	CONSTRAINT "aparencias_link_chave_valida" CHECK("aparencias_link"."chave_predefinida" IN ('padrao', 'cor-areia', 'cor-ceu', 'cor-lavanda', 'cor-menta', 'cor-nevoa', 'gradiente-amanhecer', 'gradiente-oceano', 'gradiente-campo', 'gradiente-aurora', 'cor-gelo', 'cor-pessego', 'gradiente-pastel', 'gradiente-brisa', 'radial-luar', 'radial-pessego', 'radial-lagoa', 'malha-primavera', 'malha-entardecer')),
	CONSTRAINT "aparencias_link_formato_valido" CHECK("aparencias_link"."gradiente_formato" IN ('linear', 'radial')),
	CONSTRAINT "aparencias_link_angulo_intervalo" CHECK("aparencias_link"."gradiente_angulo" BETWEEN 0 AND 360),
	CONSTRAINT "aparencias_link_cor_inicial_formato" CHECK("aparencias_link"."gradiente_cor_inicial" GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
	CONSTRAINT "aparencias_link_cor_intermediaria_formato" CHECK("aparencias_link"."gradiente_cor_intermediaria" IS NULL OR "aparencias_link"."gradiente_cor_intermediaria" GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
	CONSTRAINT "aparencias_link_cor_final_formato" CHECK("aparencias_link"."gradiente_cor_final" GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
	CONSTRAINT "aparencias_link_imagem_completa" CHECK(("aparencias_link"."imagem_identificador" IS NULL) = ("aparencias_link"."imagem_formato" IS NULL) AND ("aparencias_link"."imagem_identificador" IS NULL) = ("aparencias_link"."imagem_hash" IS NULL)),
	CONSTRAINT "aparencias_link_imagem_identificador_formato" CHECK("aparencias_link"."imagem_identificador" IS NULL OR (length("aparencias_link"."imagem_identificador") BETWEEN 16 AND 64 AND "aparencias_link"."imagem_identificador" NOT GLOB '*[^0-9a-zA-Z_-]*')),
	CONSTRAINT "aparencias_link_imagem_formato_valido" CHECK("aparencias_link"."imagem_formato" IS NULL OR "aparencias_link"."imagem_formato" IN ('png', 'jpeg', 'webp')),
	CONSTRAINT "aparencias_link_imagem_hash_formato" CHECK("aparencias_link"."imagem_hash" IS NULL OR length("aparencias_link"."imagem_hash") = 64 AND "aparencias_link"."imagem_hash" NOT GLOB '*[^0-9a-f]*'),
	CONSTRAINT "aparencias_link_imagem_exige_arquivo" CHECK("aparencias_link"."tipo" <> 'imagem' OR "aparencias_link"."imagem_identificador" IS NOT NULL),
	CONSTRAINT "aparencias_link_imagem_cor_media_formato" CHECK("aparencias_link"."imagem_cor_media" IS NULL OR "aparencias_link"."imagem_cor_media" GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
	CONSTRAINT "aparencias_link_cor_titulos_formato" CHECK("aparencias_link"."cor_titulos" GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
	CONSTRAINT "aparencias_link_cor_colunas_formato" CHECK("aparencias_link"."cor_colunas" GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
	CONSTRAINT "aparencias_link_opacidade_titulos_intervalo" CHECK("aparencias_link"."opacidade_titulos" BETWEEN 0 AND 100),
	CONSTRAINT "aparencias_link_opacidade_colunas_intervalo" CHECK("aparencias_link"."opacidade_colunas" BETWEEN 0 AND 100),
	CONSTRAINT "aparencias_link_tom_texto_valido" CHECK("aparencias_link"."tom_texto" IN ('automatico', 'escuro', 'claro')),
	CONSTRAINT "aparencias_link_cor_prioridade_critica_formato" CHECK("aparencias_link"."cor_prioridade_critica" IS NULL OR "aparencias_link"."cor_prioridade_critica" GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
	CONSTRAINT "aparencias_link_cor_prioridade_alta_formato" CHECK("aparencias_link"."cor_prioridade_alta" IS NULL OR "aparencias_link"."cor_prioridade_alta" GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
	CONSTRAINT "aparencias_link_cor_prioridade_media_formato" CHECK("aparencias_link"."cor_prioridade_media" IS NULL OR "aparencias_link"."cor_prioridade_media" GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
	CONSTRAINT "aparencias_link_cor_prioridade_baixa_formato" CHECK("aparencias_link"."cor_prioridade_baixa" IS NULL OR "aparencias_link"."cor_prioridade_baixa" GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]')
);
